contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Parameterize by a dummy uint to satisfy the checker requirement of having at least one input.
    // The test calls refund once and asserts the invariant about balances and success/revert.
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // record balances before calling refund
        uint256 beforeContract = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool succeeded;
        // call refund and observe whether it reverted
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            succeeded = false;
        } else {
            succeeded = true;
        }

        uint256 afterContract = address(c).balance;
        uint256 afterThis = address(this).balance;

        // If refund reverted, balances must be unchanged.
        // If it succeeded, contract balance decreased by some amount d (0..beforeContract)
        // and this contract's balance increased by exactly the same amount d.
        // Expressed without relying on any non-public state.
        assert(
            (!succeeded && afterContract == beforeContract && afterThis == beforeThis)
            || (succeeded && afterContract <= beforeContract && afterThis >= beforeThis && (beforeContract - afterContract) == (afterThis - beforeThis))
        );
    }

    // receive to accept Ether transferred from C during refund
    receive() external payable {}
}

