// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 beforeContract = address(c).balance;
        uint256 beforeThis = address(this).balance;
        bool succeeded;
        try c.refund() {
            succeeded = true;
        } catch {
            succeeded = false;
        }
        uint256 afterContract = address(c).balance;
        uint256 afterThis = address(this).balance;
        assertTrue((!succeeded && afterContract == beforeContract && afterThis == beforeThis)
            || (succeeded && afterContract <= beforeContract && afterThis >= beforeThis && (beforeContract - afterContract) == (afterThis - beforeThis)));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
